/* app30: Home Equity & Refinance Products (HELOC · HELOAN · VA refi · conventional/FHA refi · reverse mortgage + calculators) · Referral Partner Playbooks (8 partner types · 90-day plan · 200 targets in CA/IL/NV/FL/AZ · templates · tracker) · Annual Mortgage Review (client profile analyzer · SOP · scripts · review log).
   Planning estimates only — not a loan offer, rate quote or tax/legal advice. Verify current agency limits and lender guidelines. */
const eqAm=(P,r,n,m)=>{const mr=r/100/12;const pay=P<=0||n<=0?0:(mr?P*mr/(1-Math.pow(1+mr,-n)):P/n);let b=P,int=0;for(let i=0;i<Math.min(m,n);i++){const it=b*mr;int+=it;b=b-(pay-it)}return{pay,int,bal:Math.max(0,b)}};
const cfg=()=>Object.assign({nmls:"",disclosure:"NMLS #____ | Equal Housing Opportunity."},store.get("profile",{}));
const eqNum=(id,l,v,st)=>numf(id,l,v,st||"any");
PB_WORKFLOWS.push(
PB("PB47","Annual mortgage review done → summary + follow-ups","annual.review_done","Sends the written review summary, schedules the 30/90-day follow-ups, and logs the review in the CRM.",["Webhook","Gmail: send the summary to the client (human-approved)","Zoho: log note + next review date","Tasks: 30-day and 90-day follow-ups","Slack: notify team of any opportunity"],"Drafts the plain-language summary","Sends after Steven approves","Reviews opportunities","same day",["name","email","phone","next_review","top_opportunity","review_date"],{name:"Maria Lopez",email:"maria@example.com",phone:"7025550100",next_review:"2027-10-20",top_opportunity:"VA IRRRL",review_date:"2026-10-20"}),
PB("PB48","Annual review due (11 months) → outreach","annual.review_due","Starts the invitation sequence for clients whose annual review is due.",["Webhook / scheduled check","SMS/Email: invite to a 20-minute review","Task: ISA call if no reply in 3 days"],"Personalizes the invite","Calls and books","Runs the review","daily",["name","phone","email","last_review","due_date"],{name:"Maria Lopez",phone:"7025550100",email:"maria@example.com",last_review:"2025-10-20",due_date:"2026-10-20"}),
PB("PB49","Referral partner logged → thank-you + CRM","partner.logged","Logs a partner meeting or referral, sends a thank-you and sets the next touch.",["Webhook","Zoho: create/update partner contact + note","Gmail: thank-you (human-approved)","Task: next touch date"],"Drafts the thank-you","Sends thank-you and handwritten note","Reviews partner KPIs","same day",["partner","type","state","outcome","next_step","next_date"],{partner:"Sample Realty Group",type:"realtor",state:"CA",outcome:"Meeting held",next_step:"Send one-pager",next_date:"2026-10-27"}));
const EQ_NOTE='<p class="sm mut">Planning estimates only — not a loan offer, rate quote, or tax/legal advice. Verify current limits (HECM max claim, county limits), funding-fee tables and lender overlays before advising.</p>';
const eqProd=k=>EQ_PRODUCTS.find(p=>p.k===k);
const eqCard=p=>`<div class="card"><h4>${esc(p.n)} <span class="tag">${esc(p.grp)}</span></h4><p class="sm">${esc(p.what)}</p><div class="grid g2"><div><b class="sm">Best for</b>${omList(p.who)}<b class="sm">How it works</b><ol class="sm" style="margin:4px 0 0 18px">${p.flow.map(x=>`<li style="margin:3px 0">${esc(x)}</li>`).join("")}</ol></div><div><b class="sm">Documents</b>${omList(p.docs)}<b class="sm" style="color:var(--good)">Pros</b>${omList(p.pros)}<b class="sm" style="color:var(--warn)">Cons / watch-outs</b>${omList(p.cons)}</div></div><b class="sm">Compliance &amp; advice guardrails</b>${omList(p.comp)}<div class="callout" style="margin-top:8px"><b class="sm">Talk track</b><div class="sm">${esc(p.script)}</div></div><div class="row"><button class="btn ghost sm eq-cp" data-k="${p.k}">Copy talk track</button></div></div>`;

/* ---------------- Equity & Refi Products ---------------- */
PAGE.equity={html:()=>`<div class="card" style="border-left:4px solid var(--accent,#c9a227)"><h3 style="margin:0">Home Equity, Refinance &amp; Reverse Mortgages <span class="sub">HELOC · HELOAN · VA IRRRL / cash-out / Type I · conventional &amp; FHA refi · HECM · calculators</span></h3><p class="sm mut" style="margin:6px 0 0">Everything you need to explain, qualify and set up each equity and refinance path — plus calculators to compare them for a client. No rates are quoted here.</p></div>${omTabs("eqtab","eq","over",[]).wrap()}`,
mount(){const tabs=[
 ["over","Compare all",()=>`<div class="card" style="overflow:auto"><table><thead><tr>${EQ_COMPARE[0].map(h=>`<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${EQ_COMPARE.slice(1).map(r=>`<tr>${r.map((c,i)=>`<td class="${i?"sm":""}">${i?esc(c):"<b>"+esc(c)+"</b>"}</td>`).join("")}</tr>`).join("")}</tbody></table></div><div class="card"><h4>Fast decision guide</h4>${omList(["First-lien rate BELOW today's market → keep it; consider HELOC (flexible) or HELOAN (fixed).","First-lien rate ABOVE market and a need for cash → cash-out refinance (VA cash-out for veterans: higher LTV, no monthly MI).","Veteran with a VA loan, rate drop ≥0.5% → IRRRL first (no appraisal, 0.5% funding fee).","FHA or conventional borrower paying MI with a VA entitlement → price a VA Type I / cash-out to remove MI.","62+ with large equity and a cash-flow goal → compare HECM line of credit to HELOC; require counseling and family/advisor involvement.","Need is one-time and known → HELOAN; ongoing/uncertain → HELOC."])}</div><div class="card"><h4>Questions clients ask</h4>${EQ_FAQ.map(f=>`<details style="margin:6px 0"><summary class="sm"><b>${esc(f[0])}</b></summary><p class="sm">${esc(f[1])}</p></details>`).join("")}</div>${EQ_NOTE}`],
 ["prod","Product playbooks",()=>`<div class="card"><div class="grid g3">${sel("eq_p","Product",EQ_PRODUCTS.map(p=>[p.k,p.n]),store.get("eqp","heloc"))}</div></div><div id="eq_pd"></div>`,
  ()=>{const draw=()=>{const p=eqProd($("#eq_p").value);store.set("eqp",p.k);$("#eq_pd").innerHTML=eqCard(p)};$("#eq_p").onchange=draw;$("#eq_pd").addEventListener("click",e=>{const b=e.target.closest(".eq-cp");if(b){copy(eqProd(b.dataset.k).script);toast("Copied")}});draw()}],
 ["va","VA refinance map",()=>`${EQ_PRODUCTS.filter(p=>p.grp==="VA refinance").map(eqCard).join("")}<div class="card"><h4>VA refinance tester</h4><div class="grid g3">${eqNum("vr_days","Days since first payment due",240,1)}${eqNum("vr_pay","Payments made",8,1)}${eqNum("vr_old","Current rate %",6.875,0.125)}${eqNum("vr_new","New rate %",6.0,0.125)}${sel("vr_ty","Loan being replaced",[["fixed","VA fixed → fixed"],["arm","VA ARM → fixed"],["lowerterm","Shorter term"]],"fixed")}${chkf("vr_ex","Exempt from funding fee (VA disability comp)",false)}</div><div id="vr_out"></div></div>${EQ_NOTE}`,
  ()=>{const draw=()=>{const d=+$("#vr_days").value,p=+$("#vr_pay").value,o=+$("#vr_old").value,n=+$("#vr_new").value,t=$("#vr_ty").value;const ok1=d>=210&&p>=6,drop=o-n,ok2=t==="arm"||t==="lowerterm"||drop>=0.5-1e-9;$("#vr_out").innerHTML=`<table><tbody><tr><td>Seasoning (210 days AND 6 payments)</td><td>${ok1?'<span class="tag good">met</span>':`<span class="tag warn">not yet — ${Math.max(0,210-d)} days / ${Math.max(0,6-p)} payments to go</span>`}</td></tr><tr><td>Rate benefit (fixed→fixed needs ≥0.5% drop)</td><td>${ok2?`<span class="tag good">${t==="fixed"?drop.toFixed(3)+"% drop":"allowed type"}</span>`:`<span class="tag warn">${drop.toFixed(3)}% drop — below 0.5%</span>`}</td></tr><tr><td>Funding fee</td><td>${$("#vr_ex").checked?"exempt":"0.5% of loan amount (IRRRL)"}</td></tr><tr><td>Recoupment</td><td>Fees must be recouped within 36 months — use the Refi break-even tab.</td></tr></tbody></table>`};["vr_days","vr_pay","vr_old","vr_new","vr_ty","vr_ex"].forEach(i=>$("#"+i).oninput=$("#"+i).onchange=draw);draw()}],
 ["cmp","HELOC vs HELOAN vs cash-out",()=>`<div class="card"><h4>Keep the first lien or refinance everything?</h4><div class="grid g3">${eqNum("c_val","Home value $",700000,5000)}${eqNum("c_b1","First mortgage balance $",360000,1000)}${eqNum("c_r1","First mortgage rate %",3.25,0.125)}${eqNum("c_y1","Remaining years",26,1)}${eqNum("c_cash","Cash needed $",80000,1000)}${eqNum("c_rh","HELOC rate %",8.5,0.125)}${eqNum("c_rl","HELOAN rate %",8.0,0.125)}${eqNum("c_rn","Cash-out refi rate % (new 30-yr)",6.5,0.125)}${eqNum("c_ch","HELOC/HELOAN closing $",600,50)}${eqNum("c_cn","Cash-out refi closing % of loan",2.0,0.1)}${eqNum("c_hy","Years to compare",7,1)}${eqNum("c_ty","HELOAN / HELOC repayment years",15,1)}</div></div><div class="grid g3" id="c_cards"></div><div class="card"><div id="c_note"></div></div>${EQ_NOTE}`,
  ()=>{const draw=()=>{const v=+$("#c_val").value,b1=+$("#c_b1").value,r1=+$("#c_r1").value,y1=+$("#c_y1").value,cash=+$("#c_cash").value,rh=+$("#c_rh").value,rl=+$("#c_rl").value,rn=+$("#c_rn").value,ch=+$("#c_ch").value,cn=+$("#c_cn").value,hy=+$("#c_hy").value,ty=+$("#c_ty").value,m=hy*12;
   const f1=eqAm(b1,r1,y1*12,m);const h=eqAm(cash,rh,ty*12,m),l=eqAm(cash,rl,ty*12,m);const newL=b1+cash,cc=newL*cn/100;const rf=eqAm(newL,rn,360,m);
   const opts=[["Keep 1st + HELOC (amortized)",f1.pay+h.pay,f1.int+h.int+ch,f1.bal+h.bal,(b1+cash)/v*100,(b1*r1+cash*rh)/(b1+cash)],["Keep 1st + HELOAN",f1.pay+l.pay,f1.int+l.int+ch,f1.bal+l.bal,(b1+cash)/v*100,(b1*r1+cash*rl)/(b1+cash)],["Cash-out refinance",rf.pay,rf.int+cc,rf.bal,newL/v*100,rn]];
   const best=opts.reduce((a,o,i)=>o[2]<opts[a][2]?i:a,0);
   $("#c_cards").innerHTML=opts.map((o,i)=>`<div class="card" ${i===best?'style="border:2px solid var(--good)"':""}><h4>${o[0]} ${i===best?'<span class="tag good">lowest cost</span>':""}</h4><table><tbody><tr><td>Monthly payment (P&amp;I)</td><td><b>${money(o[1])}</b></td></tr><tr><td>Interest + fees over ${hy} yrs</td><td><b>${money(o[2])}</b></td></tr><tr><td>Balance owed after ${hy} yrs</td><td>${money(o[3])}</td></tr><tr><td>Combined LTV</td><td>${o[4].toFixed(0)}%</td></tr><tr><td>Blended rate</td><td>${o[5].toFixed(2)}%</td></tr></tbody></table></div>`).join("");
   $("#c_note").innerHTML=`<p class="sm">Cheapest on interest + fees over ${hy} years: <b>${opts[best][0]}</b>. Compare ending balances too — a lower payment with a bigger balance is not always cheaper. HELOC rates are variable; the HELOC line shows an amortized payment for comparison only. ${(b1+cash)/v>0.85?'<span class="tag warn">Combined LTV above 85% — many lenders will not approve a HELOC/HELOAN.</span>':""}</p>`};$$("[id^=c_]").forEach(e=>e.oninput=draw);draw()}],
 ["be","Refi break-even / IRRRL",()=>`<div class="card"><h4>Is the refinance worth it?</h4><div class="grid g3">${eqNum("b_bal","Current balance $",420000,1000)}${eqNum("b_r0","Current rate %",6.875,0.125)}${eqNum("b_y0","Remaining years",27,1)}${eqNum("b_r1","New rate %",6.0,0.125)}${eqNum("b_y1","New term (years)",30,1)}${eqNum("b_cc","Closing costs $ (excluding taxes/escrow)",2500,100)}${eqNum("b_ff","Funding fee %",0.5,0.05)}${chkf("b_roll","Roll costs into the loan",true)}</div></div><div class="grid g2"><div class="card" id="b_out"></div><div class="card"><div id="b_meter"></div><div id="b_flag"></div></div></div>${EQ_NOTE}`,
  ()=>{const draw=()=>{const bal=+$("#b_bal").value,r0=+$("#b_r0").value,y0=+$("#b_y0").value,r1=+$("#b_r1").value,y1=+$("#b_y1").value,cc=+$("#b_cc").value,ff=+$("#b_ff").value,roll=$("#b_roll").checked;const fee=bal*ff/100,costs=cc+fee;const newL=roll?bal+costs:bal;const p0=eqAm(bal,r0,y0*12,0).pay,p1=eqAm(newL,r1,y1*12,0).pay;const save=p0-p1;const rec=save>0?costs/save:Infinity;const tot0=p0*y0*12,tot1=p1*y1*12+(roll?0:costs);
   $("#b_out").innerHTML=`<table><tbody><tr><td>Current P&amp;I</td><td>${money2(p0)}</td></tr><tr><td>New P&amp;I (${money(newL)})</td><td>${money2(p1)}</td></tr><tr><td><b>Monthly savings</b></td><td><b style="color:${save>0?"var(--good)":"var(--bad)"}">${money2(save)}</b></td></tr><tr><td>Total costs (closing + funding fee)</td><td>${money(costs)}</td></tr><tr><td><b>Break-even (months)</b></td><td><b>${isFinite(rec)?rec.toFixed(1):"never"}</b></td></tr><tr><td>Total paid, remaining life vs new</td><td>${money(tot0)} → ${money(tot1)}</td></tr></tbody></table>`;
   vizMeter($("#b_meter"),Math.min(isFinite(rec)?rec:60,60),0,60,[[60,"var(--good)"],[100,"var(--bad)"]],{label:"Months to recoup (VA limit: 36)"});$("#b_flag").innerHTML=`<p class="sm">${!isFinite(rec)?"No monthly savings — not a payment-reduction refinance.":rec<=36?'<span class="tag good">Recoups within 36 months</span>':'<span class="tag warn">Over 36 months — fails the VA IRRRL recoupment test</span>'} ${y1>y0?"<br>Longer term lowers the payment but may raise total interest — disclose it.":""}</p>`};$$("[id^=b_]").forEach(e=>e.oninput=e.onchange=draw);draw()}],
 ["hecm","Reverse mortgage estimator",()=>`<div class="card"><h4>HECM illustration</h4><div class="grid g3">${eqNum("h_age","Age of youngest borrower",72,1)}${eqNum("h_val","Home value $",800000,5000)}${eqNum("h_lim","HECM max claim limit $ (verify yearly)",1249125,1000)}${eqNum("h_lien","Existing mortgage to pay off $",150000,1000)}${eqNum("h_plf","Principal limit factor % (use your software's)",0,0.1)}${eqNum("h_cost","Other closing/servicing costs $",9000,500)}${eqNum("h_g","Line-of-credit growth rate % (rate + 0.5% MIP)",7.0,0.125)}${eqNum("h_y","Years to illustrate",10,1)}</div><p class="sm mut">PLF left at 0 uses a rough placeholder by age — real principal limit factors depend on the expected rate and age and must come from your reverse lender's software. This is an illustration only.</p></div><div class="grid g2"><div class="card" id="h_out"></div><div class="card"><div id="h_ch"></div></div></div>${EQ_NOTE}`,
  ()=>{const draw=()=>{const age=+$("#h_age").value,val=+$("#h_val").value,lim=+$("#h_lim").value,lien=+$("#h_lien").value,cost=+$("#h_cost").value,g=+$("#h_g").value,yrs=+$("#h_y").value;let plf=+$("#h_plf").value/100;const ph=!plf;if(!plf)plf=Math.max(0.3,Math.min(0.7,0.36+(age-62)*0.0112));const mca=Math.min(val,lim),pl=mca*plf,mip=mca*0.02,net=pl-lien-mip-cost;
   $("#h_out").innerHTML=`<table><tbody><tr><td>Maximum claim amount</td><td>${money(mca)}</td></tr><tr><td>Principal limit factor</td><td>${(plf*100).toFixed(1)}% ${ph?'<span class="tag warn">placeholder</span>':""}</td></tr><tr><td>Principal limit</td><td>${money(pl)}</td></tr><tr><td>− Existing mortgage payoff</td><td>${money(lien)}</td></tr><tr><td>− Initial MIP (2% of max claim)</td><td>${money(mip)}</td></tr><tr><td>− Other costs</td><td>${money(cost)}</td></tr><tr><td><b>Estimated net proceeds / line</b></td><td><b style="color:${net>0?"var(--good)":"var(--bad)"}">${money(net)}</b></td></tr></tbody></table><p class="sm mut">${net<=0?"Existing liens and costs consume the principal limit — a reverse mortgage may not work now.":"Counseling is required before application; include family/advisors if the client wishes."}</p>`;
   const pts=[];for(let i=0;i<=yrs;i++)pts.push(Math.max(0,net)*Math.pow(1+g/100,i));$("#h_ch").innerHTML=`<h4>Unused line of credit growth <span class="sub">if untouched</span></h4><svg viewBox="0 0 300 130" width="100%" role="img"><polyline fill="none" stroke="var(--acc,#c9a227)" stroke-width="3" points="${pts.map((v,i)=>`${10+i/(yrs||1)*280},${120-(v-pts[0])/(Math.max(1,pts[pts.length-1]-pts[0]))*100}`).join(" ")}" stroke-dasharray="600" stroke-dashoffset="600"><animate attributeName="stroke-dashoffset" from="600" to="0" dur="1s" fill="freeze"/></polyline><text x="10" y="128" font-size="9" fill="currentColor">now ${money(pts[0])}</text><text x="290" y="14" font-size="9" text-anchor="end" fill="currentColor">${yrs} yrs ${money(pts[pts.length-1])}</text></svg>`};$$("[id^=h_]").forEach(e=>e.oninput=draw);draw()}],
 ["ltv","Equity & max loan tiers",()=>`<div class="card"><div class="grid g3">${eqNum("l_val","Home value $",700000,5000)}${eqNum("l_bal","Total mortgage balance $",360000,1000)}</div></div><div class="card" id="l_out"></div>${EQ_NOTE}`,
  ()=>{const draw=()=>{const v=+$("#l_val").value,b=+$("#l_bal").value;const rows=[["Conventional cash-out (primary)",80],["FHA cash-out",80],["VA cash-out (lender overlay often 90%)",90],["VA cash-out (VA maximum)",100],["HELOC / HELOAN (CLTV, typical)",85]];$("#l_out").innerHTML=`<p class="sm">Current LTV: <b>${(b/v*100).toFixed(1)}%</b> · Equity: <b>${money(v-b)}</b></p><table><thead><tr><th>Path</th><th>Max LTV</th><th>Max total debt</th><th>Cash available (before costs)</th></tr></thead><tbody>${rows.map(r=>{const m=v*r[1]/100;return `<tr><td>${esc(r[0])}</td><td>${r[1]}%</td><td>${money(m)}</td><td><b>${money(Math.max(0,m-b))}</b></td></tr>`}).join("")}</tbody></table>`};$$("[id^=l_]").forEach(e=>e.oninput=draw);draw()}]
 ];omTabs("eqtab","eq","over",tabs).run()}};

/* ---------------- Referral Partner Playbooks ---------------- */
const RP_STATUS=["Not started","Researching","Contacted","Meeting held","Active partner","Not a fit"];
const rpTy=k=>RP_TYPES.find(t=>t.k===k);
PAGE.refer={html:()=>`<div class="card" style="border-left:4px solid var(--accent,#c9a227)"><h3 style="margin:0">Referral Partner Playbooks <span class="sub">realtors · CPAs · tax advisors · wealth advisors · family offices · attorneys · senior advisors · ${RP_TARGETS.length} targets in CA · IL · NV · FL · AZ</span></h3><p class="sm mut" style="margin:6px 0 0"><b>Honest note:</b> the ${RP_TARGETS.length} targets are <b>organizations, associations and national firms</b> in your five licensed states — not individual people. I did not invent contacts. Use the search link on each row to find the local chapter or branch, then log the person you meet. RESPA §8 forbids paying for referrals — everything here is education and service.</p></div>${omTabs("rptab2","rpt","types",[]).wrap()}`,
mount(){const tabs=[
 ["types","Partner playbooks",()=>`<div class="card"><div class="grid g3">${sel("rp_t","Partner type",RP_TYPES.map(t=>[t.k,t.n]),store.get("rp_t","realtor"))}</div></div><div id="rp_d"></div>`,
  ()=>{const draw=()=>{const t=rpTy($("#rp_t").value);store.set("rp_t",t.k);$("#rp_d").innerHTML=`<div class="card"><h4>${esc(t.n)}</h4><p class="sm"><b>Why they refer:</b> ${esc(t.why)}</p><div class="grid g2"><div><b class="sm">What to lead with</b>${omList(t.lead)}<b class="sm">Products to bring up</b>${omList(t.products)}<b class="sm">Meeting plan (20 min)</b>${omList(t.meeting)}</div><div><b class="sm">Follow-up sequence</b>${omList(t.follow)}<b class="sm">Common objections</b>${t.obj.map(o=>`<p class="sm"><b>“${esc(o[0])}”</b><br>${esc(o[1])}</p>`).join("")}<b class="sm" style="color:var(--warn)">Compliance</b>${omList(t.comp)}</div></div><div class="callout"><b class="sm">First-touch talk track</b><div class="sm">${esc(t.first)}</div></div><p class="sm"><b>KPIs:</b> ${esc(t.kpi.join(" · "))}</p><p class="sm"><b>Resources to build:</b> ${esc(t.resources.join(" · "))}</p><div class="row"><button class="btn ghost sm" id="rp_cp">Copy first-touch</button><button class="btn ghost sm" id="rp_one">Generate one-pager</button></div><pre id="rp_op" class="sm" style="white-space:pre-wrap;display:none"></pre></div>`;
   $("#rp_cp").onclick=()=>{copy(t.first);toast("Copied")};$("#rp_one").onclick=()=>{const o=`${t.n.toUpperCase()} — PARTNER ONE-PAGER\nSteven Shearrill · Patriot Pacific Financial · NMLS ${cfg().nmls||"____"}\n\nWhat I do for your clients:\n${t.lead.map(x=>"• "+x).join("\n")}\n\nHow we work:\n• Same-day response to you and your client\n• Weekly status update on shared files\n• Clear written options with total-cost comparisons\n\nProducts: ${t.products.join(", ")}\n\nNext step: 20-minute intro this week.\n\nEqual Housing Opportunity. No compensation for referrals; educational partnership only.`;$("#rp_op").style.display="block";$("#rp_op").textContent=o;copy(o);toast("One-pager copied")}};$("#rp_t").onchange=draw;draw()}],
 ["plan","90-day launch plan",()=>`<div class="card"><h4>From zero to a partner pipeline</h4><table><thead><tr><th>When</th><th>Focus</th><th>Do this</th></tr></thead><tbody>${RP_PLAN90.map(r=>`<tr><td><b>${esc(r[0])}</b></td><td>${esc(r[1])}</td><td class="sm">${esc(r[2])}</td></tr>`).join("")}</tbody></table><p class="sm mut">Weekly rhythm: 5 new meetings, 10 follow-ups, 1 education event/month, 1 partner thank-you note each day.</p></div><div class="card"><h4>Where to start (suggested)</h4>${omList(["Start with Realtors and CPAs in your home metro; add wealth advisors once you have two proof points.","Use the Annual Mortgage Review as the 'give' for every partner type — it helps their clients without a pitch.","Run one education event per month rotating partner types (VA class, HELOC/HECM planning, self-employed income).","Track every touch in the Tracker tab; fire PB49 to log it in Zoho."])}</div>`],
 ["targets","200 targets (5 states)",()=>`<div class="card"><div class="row" style="flex-wrap:wrap;gap:8px">${sel("rt_s","State",[["","All states"],...Object.entries(RP_STATES)],"")}${sel("rt_ty","Type",[["","All types"],...RP_TYPES.map(t=>[t.k,t.n])],"")}${sel("rt_p","Priority",[["","All"],["A","A — start here"],["B","B"],["C","C"]],"")}${sel("rt_st","Status",[["","All"],...RP_STATUS.map(s=>[s,s])],"")}<input id="rt_q" placeholder="Search organization…" style="flex:1;min-width:180px"><button class="btn ghost sm" id="rt_csv">Export CSV</button></div><div id="rt_sh" style="margin-top:8px"></div><p class="sm mut" id="rt_n"></p></div><div class="card" style="overflow:auto"><div id="rt_t"></div></div>`,
  ()=>{const S=()=>store.get("rp_status",{});const rows=()=>{const f={s:$("#rt_s").value,ty:$("#rt_ty").value,p:$("#rt_p").value,st:$("#rt_st").value,q:$("#rt_q").value.toLowerCase()};const ST=S();return RP_TARGETS.filter(t=>(!f.s||t.state===f.s)&&(!f.ty||t.type===f.ty)&&(!f.p||t.pri===f.p)&&(!f.st||(ST[t.id]?.s||"Not started")===f.st)&&(!f.q||t.org.toLowerCase().includes(f.q)))};
   const draw=()=>{const R=rows(),ST=S();$("#rt_n").textContent=`${R.length} of ${RP_TARGETS.length} targets`;const parts=RP_STATUS.map((s,i)=>({l:s,v:RP_TARGETS.filter(t=>(ST[t.id]?.s||"Not started")===s).length,c:["#999","#4682b4","#c9a227","#8e44ad","#2e8b57","#c0392b"][i]})).filter(p=>p.v>0);vizShare($("#rt_sh"),parts);
    $("#rt_t").innerHTML=`<table><thead><tr><th>ID</th><th>State</th><th>Type</th><th>Organization</th><th>Pri</th><th>Status</th><th>Notes / who you met</th><th></th></tr></thead><tbody>${R.map(t=>{const s=ST[t.id]||{};return `<tr><td class="sm mut">${t.id}</td><td>${t.state}</td><td class="sm">${esc(rpTy(t.type).n)}</td><td><b>${esc(t.org)}</b><div class="sm mut">${esc(t.scope)}</div></td><td>${t.pri}</td><td><select class="rt-s" data-id="${t.id}">${RP_STATUS.map(x=>`<option ${x===(s.s||"Not started")?"selected":""}>${x}</option>`).join("")}</select></td><td><input class="rt-n" data-id="${t.id}" value="${esc(s.n||"")}" placeholder="name · phone · email" style="min-width:180px"></td><td><a class="btn ghost sm" target="_blank" rel="noopener" href="https://www.google.com/search?q=${encodeURIComponent(t.q)}">Find local ↗</a></td></tr>`}).join("")}</tbody></table>`};
   ["rt_s","rt_ty","rt_p","rt_st"].forEach(i=>$("#"+i).onchange=draw);$("#rt_q").oninput=draw;
   $("#rt_t").addEventListener("change",e=>{const x=e.target.closest(".rt-s");if(x){const A=S();A[x.dataset.id]=Object.assign(A[x.dataset.id]||{},{s:x.value});store.set("rp_status",A);draw()}});
   $("#rt_t").addEventListener("input",e=>{const x=e.target.closest(".rt-n");if(x){const A=S();A[x.dataset.id]=Object.assign(A[x.dataset.id]||{},{n:x.value});store.set("rp_status",A)}});
   $("#rt_csv").onclick=()=>{const ST=S();cnDownload("referral-targets.csv",cnToCSV(["id","state","type","org","scope","pri","status","notes","search"],rows().map(t=>({id:t.id,state:t.state,type:t.type,org:t.org,scope:t.scope,pri:t.pri,status:ST[t.id]?.s||"Not started",notes:ST[t.id]?.n||"",search:"https://www.google.com/search?q="+encodeURIComponent(t.q)})))) };draw()}],
 ["tpl","Scripts & templates",()=>`<div class="grid g2">${RP_TEMPLATES.map((t,i)=>`<div class="card"><h4>${esc(t[0])}</h4><pre class="sm" style="white-space:pre-wrap;max-height:220px;overflow:auto">${esc(t[1])}</pre><button class="btn ghost sm rp-cp" data-i="${i}">Copy</button></div>`).join("")}</div>`,
  ()=>{$$(".rp-cp").forEach(b=>b.onclick=()=>{copy(RP_TEMPLATES[+b.dataset.i][1].replace("{disclosure}",cfg().disclosure||""));toast("Copied")})}],
 ["comp","Compliance",()=>`<div class="card"><h4>Rules of the road</h4><table><tbody>${RP_COMPLIANCE.map(c=>`<tr><td><b>${esc(c[0])}</b></td><td class="sm">${esc(c[1])}</td></tr>`).join("")}</tbody></table><p class="sm mut">Have your compliance officer or attorney review any co-marketing, lead-sharing or event sponsorship before you do it.</p></div>`],
 ["track","Partner tracker",()=>`<div class="card"><h4>Log a partner touch</h4><div class="grid g3"><div><label>Partner / organization</label><input id="pt_n"></div>${sel("pt_t","Type",RP_TYPES.map(t=>[t.k,t.n]),"realtor")}${sel("pt_s","State",Object.entries(RP_STATES),"CA")}${sel("pt_o","Outcome",["Meeting held","Sent materials","Referral received","Loan closed","Event hosted","No response"].map(x=>[x,x]),"Meeting held")}<div><label>Next step</label><input id="pt_x"></div><div><label>Next date</label><input type="date" id="pt_d"></div></div><button class="btn sm" id="pt_add" style="margin-top:8px">Log</button></div><div class="grid g4" id="pt_k"></div><div id="pt_l"></div>`,
  ()=>{const L=()=>store.get("rp_log",[]);const draw=()=>{const A=L();const c=o=>A.filter(x=>x.o===o).length;$("#pt_k").innerHTML=[["Touches logged",A.length],["Meetings",c("Meeting held")],["Referrals received",c("Referral received")],["Loans closed",c("Loan closed")]].map(k=>`<div class="card"><div class="sm mut">${k[0]}</div><div style="font-size:24px;font-weight:700">${k[1]}</div></div>`).join("");$("#pt_l").innerHTML=A.length?`<div class="card" style="overflow:auto"><table><thead><tr><th>Date</th><th>Partner</th><th>Type</th><th>State</th><th>Outcome</th><th>Next</th><th></th></tr></thead><tbody>${A.map((x,i)=>`<tr><td>${esc(x.d)}</td><td><b>${esc(x.n)}</b></td><td class="sm">${esc(rpTy(x.t).n)}</td><td>${x.s}</td><td>${esc(x.o)}</td><td class="sm">${esc(x.x||"")} ${x.nd?"· "+esc(x.nd):""}</td><td><button class="btn ghost sm pt-x" data-i="${i}">✕</button></td></tr>`).join("")}</tbody></table></div>`:'<div class="card mut">No touches yet.</div>'};
   $("#pt_add").onclick=()=>{const n=$("#pt_n").value.trim();if(!n)return toast("Partner name");const A=L();const e={d:cnToday(),n,t:$("#pt_t").value,s:$("#pt_s").value,o:$("#pt_o").value,x:$("#pt_x").value,nd:$("#pt_d").value};A.unshift(e);store.set("rp_log",A);if(typeof emit==="function")emit("partner.logged",{partner:n,type:e.t,state:e.s,outcome:e.o,next_step:e.x,next_date:e.nd});if(e.x&&typeof boardAdd==="function")boardAdd({t:`Partner: ${n} — ${e.x}`,due:e.nd?new Date(e.nd).toISOString():"",owner:"ISA",src:"partner"},false);$("#pt_n").value=$("#pt_x").value="";draw()};
   $("#pt_l").addEventListener("click",e=>{const x=e.target.closest(".pt-x");if(x){const A=L();A.splice(+x.dataset.i,1);store.set("rp_log",A);draw()}});draw()}]
 ];omTabs("rptab2","rpt","types",tabs).run()}};

/* ---------------- Annual Mortgage Review ---------------- */
const AMR_GOALS=[["lower","Lower the payment"],["shorter","Pay off sooner / save interest"],["cash","Take cash out"],["consol","Consolidate debt"],["improve","Home improvement / ADU"],["mi","Remove mortgage insurance"],["retire","Retirement income / stay in home"],["invest","Buy an investment property"],["fixarm","Escape an adjustable rate"]];
const AMR_DEF={name:"",phone:"",email:"",age:45,mil:"vet",disab:0,occ:"primary",value:700000,year:2019,ltype:"conv",bal:420000,rate:6.5,rem:26,pay:0,mi:0,hel:0,debts:0,ccbal:0,ccrate:22,credit:"740",income:9000,goals:["lower"],mktConv:6.25,mktVA:5.9,stay:7,arm:false,notes:""};
const amrState=()=>Object.assign({},AMR_DEF,store.get("amr_cur",{}));
function amrAnalyze(c){const out=[];const v=c.value,b=c.bal+c.hel;const ltv=c.bal/v*100,cltv=b/v*100;const P=c.pay||eqAm(c.bal,c.rate,c.rem*12,0).pay;const mkt=c.ltype==="va"||c.mil==="vet"||c.mil==="ad"?c.mktVA:c.mktConv;const gap=c.rate-mkt;const goals=c.goals||[];const has=g=>goals.includes(g);
 const isVet=["vet","ad"].includes(c.mil);let health=70;
 const add=(k,score,title,why,numbers,next,prod)=>out.push({k,score:Math.max(0,Math.min(100,Math.round(score))),title,why,numbers,next,prod});
 // refi savings helper
 const refiSave=(newRate,newTerm,costs)=>{const nb=c.bal+costs;const np=eqAm(nb,newRate,newTerm*12,0).pay;const s=P-np;return{np,s,rec:s>0?costs/s:Infinity}};
 if(gap>=0.5){const cc=Math.round(c.bal*0.02);const r=refiSave(mkt,30,cc);if(c.ltype==="va"){const fee=Math.round(c.bal*0.005);const r2=refiSave(mkt,c.rem,fee+Math.round(c.bal*0.004));add("irrrl",55+Math.min(35,gap*20),"VA IRRRL (streamline)",`Rate is ${gap.toFixed(2)}% above today's VA estimate. IRRRL needs no appraisal and has a 0.5% funding fee (unless exempt).`,`Est. P&I ${money2(P)} → ${money2(r2.np)} (save ${money2(r2.s)}/mo; break-even ${isFinite(r2.rec)?r2.rec.toFixed(0):"n/a"} months). Must recoup in ≤36 months and meet seasoning.`,"Verify seasoning (210 days + 6 payments), payment history, and run the Refi break-even tab; order payoff and quote.","irrrl")}else{add("rt",50+Math.min(35,gap*18),"Rate/term refinance",`Rate is ${gap.toFixed(2)}% above today's estimate.`,`Est. P&I ${money2(P)} → ${money2(r.np)} (save ${money2(r.s)}/mo; break-even ${isFinite(r.rec)?r.rec.toFixed(0):"n/a"} months on ~${money(cc)} costs).`,"Run a full comparison and confirm net tangible benefit; consider term and total interest.","concash")}}
 if(isVet&&c.ltype!=="va"&&(c.mi>0||c.ltype==="fha"||has("mi")||has("cash")||has("consol")||gap>0.25)){const cap=Math.round(v*0.9-c.bal);add("vacash",58+(c.mi>0?18:0)+(has("cash")||has("consol")?8:0),"VA cash-out / Type I into a VA loan",`Veteran/service member on a ${c.ltype.toUpperCase()} loan${c.mi>0?" paying "+money(c.mi)+"/mo mortgage insurance":""}. A VA loan has no monthly MI and allows higher LTV than conventional.`,`VA cash-out at a typical 90% lender cap: up to ~${money(Math.max(0,cap))} available (VA max 100%). Funding fee 2.15% first use / 3.3% subsequent (verify) unless exempt.`,"Confirm entitlement/COE, price with VA-experienced lenders, compare funding fee vs MI saved.","vacash")}
 if(c.mi>0&&c.ltype==="conv"&&ltv<=80)add("mi",82,"Remove PMI now",`Estimated LTV ${ltv.toFixed(0)}% is at or below 80% — PMI may be removable by request (appraisal/servicer rules) or via refinance.`,`Saves about ${money(c.mi)}/mo (${money(c.mi*12)}/yr).`,"Request removal from the servicer with a current valuation; or refinance if rates also help.","concash");
 else if(c.mi>0&&c.ltype==="conv"&&ltv<=85)add("mi",55,"PMI removal within reach",`LTV ${ltv.toFixed(0)}% — close to the 80% threshold.`,`Paying PMI ${money(c.mi)}/mo.`,"Check original-value amortization date, request a valuation, or refinance when appropriate.","concash");
 if(c.mi>0&&c.ltype==="fha"&&!isVet)add("fha",62,"Get out of FHA MIP",`FHA MIP often lasts for the life of the loan; conventional refinance may eliminate it if LTV ≤80–90% and credit supports.`,`Paying about ${money(c.mi)}/mo in MIP.`,"Price a conventional refinance; compare total cost over expected stay.","fharef");
 if((has("cash")||has("improve")||has("consol")||has("invest"))&&c.rate<mkt-0.75&&cltv<=85){add("heloc",72+(c.rate<mkt-1.5?10:0),"HELOC or HELOAN — keep your low first-lien rate",`First-lien rate ${c.rate}% is well below today's ~${mkt}%. A second lien avoids refinancing the whole balance.`,`Combined LTV ${cltv.toFixed(0)}%. Estimated usable equity at 85% CLTV: ${money(Math.max(0,v*0.85-b))}.`,"Run the HELOC vs HELOAN vs cash-out comparison; choose HELOAN for a one-time cost, HELOC for ongoing/uncertain needs.","heloc")}
 else if((has("cash")||has("improve")||has("consol"))&&cltv<=90){add("cashout",58,"Cash-out refinance",`Goal includes cash and the first-lien rate is not far below market, so one new loan may be simplest.`,`Estimated cash at 80% LTV: ${money(Math.max(0,v*0.8-b))} (VA up to 90–100% for eligible veterans).`,"Run the comparison; check LLPAs and seasoning.","concash")}
 if(c.ccbal>0&&(has("consol")||c.ccbal>10000)){const cardPay=c.ccbal*0.03;const hel=eqAm(c.ccbal,mkt+2.5,180,0).pay;add("consol",60+Math.min(25,c.ccbal/2000),"Debt consolidation analysis",`${money(c.ccbal)} of ${c.ccrate}% debt. Moving it into a lower-rate secured loan can cut the payment but turns unsecured debt into debt secured by the home.`,`Typical card minimum ≈ ${money(cardPay)}/mo vs ~${money(hel)}/mo on a 15-yr second at ~${(mkt+2.5).toFixed(2)}% — show total cost, not just payment.`,"Discuss behavior and budget; pay accounts off at closing; consider whether the debt can instead be repaid directly.","heloan")}
 if(has("shorter")||(c.rate<=mkt&&c.rem>20)){const ex=Math.round(c.pay?c.pay*0.1:P*0.1);const base=eqAm(c.bal,c.rate,c.rem*12,c.rem*12);let b2=c.bal,i2=0,n2=0;const mr=c.rate/1200;while(b2>0&&n2<c.rem*12+1){const it=b2*mr;i2+=it;b2=b2-(P+ex-it);n2++}add("extra",45+(has("shorter")?20:0),"Extra principal / shorter payoff",`Adding about ${money(ex)}/mo (10% of P&I) shortens the loan and cuts interest without refinancing.`,`Interest saved ≈ ${money(base.int-i2)}; payoff ≈ ${(n2/12).toFixed(1)} years instead of ${c.rem}.`,"Confirm the servicer applies extra to principal; compare to investing the difference (advisor/CPA).","concash")}
 if(c.arm||has("fixarm"))add("arm",85,"Adjustable-rate watch",`ARM resets can raise payments sharply. Review index, margin, caps and next adjustment date.`,`Convert to a fixed rate when the reset risk outweighs the benefit.`,"Gather the note's ARM terms; price a fixed alternative (IRRRL if VA).","irrrl");
 if(c.age>=62&&(has("retire")||ltv<=60)){const mca=Math.min(v,1249125);const plf=Math.max(0.3,Math.min(0.7,0.36+(c.age-62)*0.0112));const net=mca*plf-c.bal-mca*0.02-9000;add("hecm",has("retire")?78:50,"Reverse mortgage (HECM) education",`Age ${c.age} with ${money(v-c.bal)} of equity. A HECM line of credit can be a retirement liquidity reserve or eliminate a required payment. Counseling is mandatory.`,`Illustrative net proceeds (placeholder factor): ${money(Math.max(0,net))}. Real factors come from your reverse lender's software.`,"Offer education; involve family/advisor; compare with HELOC and downsizing.","hecm")}
 if(has("invest")&&cltv<=80)add("invest",55,"Equity for an investment property",`Use a HELOC/cash-out for the down payment and a DSCR or conventional loan on the purchase.`,`Usable equity at 80% CLTV: ${money(Math.max(0,v*0.8-b))}.`,"Review reserves, rental analysis, and risk — involve CPA/advisor.","heloc");
 add("tax",35,"Insurance & property-tax tune-up","Every review: shop homeowner's insurance, verify escrow, and check property-tax assessment for reassessment relief where available.","Often finds hundreds of dollars a year.","Offer a checklist; refer to an insurance agent or tax professional (no tax advice).","");
 // health score
 let hs=70;if(ltv<=60)hs+=10;else if(ltv>85)hs-=10;if(gap>=1)hs-=15;else if(gap>=0.5)hs-=8;else if(gap<=-1)hs+=8;if(c.mi>0)hs-=6;if(c.arm)hs-=10;const dti=(P+c.mi+c.debts)/(c.income||1)*100;if(dti>45)hs-=12;else if(dti<30)hs+=6;if(c.ccbal>15000)hs-=6;hs=Math.max(0,Math.min(100,Math.round(hs)));
 out.sort((a,b)=>b.score-a.score);return{opps:out,ltv,cltv,P,gap,mkt,dti,health:hs,equity:v-b}}
function amrSummary(c,a){const top=a.opps.filter(o=>o.k!=="tax").slice(0,3);return `Hi ${c.name.split(" ")[0]||"there"},\n\nThanks for doing your annual mortgage review. Here's a plain-language summary.\n\nWhere you stand:\n• Home value (estimate): ${money(c.value)}\n• Mortgage balance${c.hel?" (+ HELOC)":""}: ${money(c.bal+c.hel)}  →  Equity: ${money(a.equity)} (loan-to-value ${a.cltv.toFixed(0)}%)\n• Current rate: ${c.rate}%  ·  P&I: ${money2(a.P)}${c.mi?`  ·  Mortgage insurance: ${money(c.mi)}/mo`:""}\n• Review health score: ${a.health}/100\n\nWhat I'd look at together:\n${top.length?top.map((o,i)=>`${i+1}. ${o.title} — ${o.why}`).join("\n"):"• Nothing urgent; your current loan looks reasonable for your goals."}\n\nNext steps:\n• Tell me which of these you'd like me to price out (no obligation)\n• Consider talking with your CPA or financial advisor about the tax and planning side — I'm happy to join that conversation\n• I'll check back in 90 days and again at your next annual review.\n\nThis is an educational estimate, not a loan offer or tax advice. Actual terms depend on a full application.\n\nSteven Shearrill\nNMLS ${cfg().nmls||"____"}\n${cfg().disclosure||""}`}
const AMR_SOP=[
 ["Before the review (prep, 15 min)",["Pull the client's file: loan type, rate, balance, closing date, program, original value","Check current rates for their product (Daily Rate Desk) and any VA/FHA changes","Note life events from CRM (job, kids, retirement, PCS, divorce, inheritance)","Gather goals questions: payment, cash, debt, retirement, investing","Decide if a partner (CPA/advisor/agent) should join"]],
 ["Invite (11 months after closing or last review)",["Send text + email invite (PB48); offer 2 time slots or booking link","If no reply in 3 days, ISA calls","Explain the benefit: 'free 20-minute check-up of your mortgage and equity'"]],
 ["Meeting agenda (20–30 min)",["1) Goals and what's changed (5)","2) Show the numbers: balance, equity, rate, payment, MI (5)","3) Options: refi, IRRRL, HELOC/HELOAN, MI removal, extra principal, reverse (if 62+) (7)","4) Risks and costs; what NOT to do (3)","5) Decide: do nothing, run quotes, or schedule follow-up (3)"]],
 ["Analysis checklist",["LTV/CLTV and equity","Rate gap vs market and break-even months","MI/MIP removal eligibility","VA: IRRRL seasoning and recoupment; funding-fee exemption status","ARM reset dates","High-rate debt and total-cost comparison","Insurance and property-tax review","Partner coordination (CPA/advisor/attorney)"]],
 ["After the meeting (same day)",["Send the written summary (human-reviewed) within 24 hours","Create tasks: 30-day and 90-day follow-ups; next annual review date","Update Zoho: notes, goals, opportunity, next review date (PB47)","If an opportunity is accepted, open the file and start the application workflow","Send a thank-you; ask for a referral and a review"]],
 ["Referral ask (natural moment)",["'Who do you know — a friend, coworker or family member — who might benefit from a check-up like this?'","'Would you introduce me to your CPA or financial advisor so we can coordinate?'","Never offer value for referrals (RESPA §8)"]]
];
const AMR_TEMPLATES=[
 ["Invite — email","Subject: Your annual mortgage check-up, {first}\n\nHi {first},\n\nIt's been about a year since we worked together on your home loan. I offer a free 20-minute annual mortgage review: I'll look at your rate, equity and options and tell you honestly whether anything is worth doing — often it isn't, and sometimes it saves real money.\n\nPick a time: {link}\n\nSteven Shearrill\n{disclosure}"],
 ["Invite — text","Hi {first}, it's Steven. Your annual mortgage check-up is due. 20 minutes, no pressure — want a time this week? {link}"],
 ["Voicemail","Hi {first}, it's Steven Shearrill. I'm calling about your free annual mortgage review — a quick look at your rate and equity to see if anything makes sense. I'll text you a link to pick a time. Talk soon."],
 ["Meeting opener","“Thanks for making time. Today I'll show where your mortgage and equity stand, tell you honestly if anything is worth doing, and leave you with a one-page summary. What are you hoping to get out of this year?”"],
 ["'Nothing to do' summary","Hi {first},\n\nGood news: after reviewing your loan, I don't see a change that clearly benefits you right now. Your rate and terms are working. I'll watch for changes and reach out if the numbers shift.\n\nQuestions any time.\n\nSteven"],
 ["Referral ask","“If this check-up was helpful, I'd be honored if you'd share my name with someone who might benefit — a friend, a coworker, or your CPA or advisor. No pressure at all.”"],
 ["Partner note (CPA/advisor)","Hi {first}, I just completed an annual mortgage review for our mutual client {client}. With their permission, I can share the numbers: [summary]. Happy to join a call if a planning discussion would help."]
];
PAGE.annual={html:()=>`<div class="card" style="border-left:4px solid var(--accent,#c9a227)"><div class="row" style="flex-wrap:wrap"><div class="sp"><h3 style="margin:0">Annual Mortgage Review <span class="sub">analyze a client's profile · opportunities · summary · follow-ups · review log</span></h3><p class="sm mut" style="margin:6px 0 0">Run it for every past client every 12 months. It's the best "give" for realtors, CPAs and advisors, and the cheapest source of refinance, HELOC and reverse-mortgage business.</p></div><div id="am_g"></div></div></div>${omTabs("amtab","am","rev",[]).wrap()}`,
mount(){const tabs=[
 ["rev","Client review",()=>{const c=amrState();const f=(id,l,v,st)=>numf("am_"+id,l,v,st||"any");return `<div class="card"><h4>Client profile</h4><div class="grid g3"><div><label>Name</label><input id="am_name" value="${esc(c.name)}"></div><div><label>Phone</label><input id="am_phone" value="${esc(c.phone)}"></div><div><label>Email</label><input id="am_email" value="${esc(c.email)}"></div>${f("age","Age",c.age,1)}${sel("am_mil","Military / VA status",[["vet","Veteran"],["ad","Active duty"],["none","Non-military"]],c.mil)}${f("disab","VA disability %",c.disab,10)}${sel("am_occ","Occupancy",[["primary","Primary"],["second","Second home"],["inv","Investment"]],c.occ)}${f("value","Home value $",c.value,5000)}${f("year","Purchase year",c.year,1)}${sel("am_ltype","Current loan",[["conv","Conventional"],["fha","FHA"],["va","VA"],["usda","USDA"],["jumbo","Jumbo"]],c.ltype)}${f("bal","Mortgage balance $",c.bal,1000)}${f("rate","Current rate %",c.rate,0.125)}${f("rem","Remaining years",c.rem,1)}${f("pay","Current P&I $ (0 = calculate)",c.pay,10)}${f("mi","Monthly MI/MIP $",c.mi,10)}${f("hel","HELOC/2nd balance $",c.hel,1000)}${f("debts","Other monthly debts $",c.debts,10)}${f("ccbal","High-rate debt balance $",c.ccbal,500)}${f("ccrate","High-rate debt APR %",c.ccrate,0.5)}${f("income","Gross monthly income $",c.income,100)}${f("mktConv","Market rate — conventional %",c.mktConv,0.125)}${f("mktVA","Market rate — VA %",c.mktVA,0.125)}${f("stay","Years they expect to stay",c.stay,1)}</div><div class="row" style="flex-wrap:wrap;margin-top:8px"><b class="sm">Goals:</b>${AMR_GOALS.map(g=>`<label class="chk"><input type="checkbox" class="am-g" value="${g[0]}" ${c.goals.includes(g[0])?"checked":""}> ${g[1]}</label>`).join("")}${chkf("am_arm","Has an adjustable-rate mortgage",c.arm)}</div><div><label>Notes</label><textarea id="am_notes" rows="2" style="width:100%">${esc(c.notes)}</textarea></div><p class="sm mut">Rates are estimates you enter — use today's Daily Rate Desk read. Nothing here is a quote.</p></div><div class="grid g4" id="am_k"></div><div id="am_o"></div><div class="card"><h4>Client summary (edit, then send)</h4><textarea id="am_s" rows="14" style="width:100%"></textarea><div class="row" style="flex-wrap:wrap"><button class="btn ghost sm" id="am_cp">Copy</button><button class="btn" id="am_save">Save review + schedule follow-ups</button><button class="btn ghost sm" id="am_new">New client</button></div><span class="sm mut" id="am_msg"></span></div>`},
  ()=>{const read=()=>{const c=amrState();const n=id=>+$("#am_"+id).value||0;Object.assign(c,{name:$("#am_name").value,phone:$("#am_phone").value,email:$("#am_email").value,age:n("age"),mil:$("#am_mil").value,disab:n("disab"),occ:$("#am_occ").value,value:n("value"),year:n("year"),ltype:$("#am_ltype").value,bal:n("bal"),rate:n("rate"),rem:n("rem"),pay:n("pay"),mi:n("mi"),hel:n("hel"),debts:n("debts"),ccbal:n("ccbal"),ccrate:n("ccrate"),income:n("income"),mktConv:n("mktConv"),mktVA:n("mktVA"),stay:n("stay"),arm:$("#am_arm").checked,notes:$("#am_notes").value,goals:$$(".am-g").filter(x=>x.checked).map(x=>x.value)});store.set("amr_cur",c);return c};
   let edited=false;const draw=()=>{const c=read();const a=amrAnalyze(c);vizGauge($("#am_g"),a.health,{label:"review health",size:110,fmt:x=>Math.round(x)+"",zones:[[50,"var(--bad)"],[75,"var(--warn)"],[101,"var(--good)"]]});
    $("#am_k").innerHTML=[["Equity",money(a.equity)],["LTV / CLTV",`${a.ltv.toFixed(0)}% / ${a.cltv.toFixed(0)}%`],["Rate gap vs market",`${a.gap>=0?"+":""}${a.gap.toFixed(2)}%`],["Debt-to-income (est.)",`${a.dti.toFixed(0)}%`]].map(k=>`<div class="card"><div class="sm mut">${k[0]}</div><div style="font-size:22px;font-weight:700">${k[1]}</div></div>`).join("");
    $("#am_o").innerHTML=`<div class="card"><h4>Opportunities, ranked <span class="sub">score = how strongly the profile supports raising it</span></h4>${a.opps.map(o=>`<div class="card" style="margin:8px 0;border-left:4px solid ${o.score>=70?"var(--good)":o.score>=50?"var(--warn)":"var(--line)"}"><div class="row"><b>${esc(o.title)}</b><span class="sp"></span><span class="tag">${o.score}</span></div><p class="sm">${esc(o.why)}</p><p class="sm"><b>Numbers:</b> ${esc(o.numbers)}</p><p class="sm"><b>Next step:</b> ${esc(o.next)}</p>${o.prod?`<a class="btn ghost sm am-pb" href="#equity" data-p="${o.prod}">Product playbook</a>`:""}</div>`).join("")}</div>`;
    if(!edited)$("#am_s").value=amrSummary(c,a)};
   $$("#am_body input,#am_body select").forEach(e=>{e.oninput=e.onchange=draw});$("#am_o").addEventListener("click",e=>{const a=e.target.closest(".am-pb");if(a){store.set("eqp",a.dataset.p);store.set("eqtab","prod")}});$("#am_s").oninput=()=>{edited=true};
   $("#am_cp").onclick=()=>{copy($("#am_s").value);toast("Summary copied")};
   $("#am_new").onclick=()=>{store.set("amr_cur",{});$("#am_body").innerHTML=tabs[0][2]();tabs[0][3]()};
   $("#am_save").onclick=()=>{const c=read();if(!c.name)return toast("Add a client name");const a=amrAnalyze(c);const R=store.get("amr_clients",[]);const next=new Date();next.setFullYear(next.getFullYear()+1);const rec={id:c.id||("a"+Date.now()),date:cnToday(),next:clIso(next),profile:c,health:a.health,top:a.opps.filter(o=>o.k!=="tax")[0]?.title||"No action",equity:a.equity,summary:$("#am_s").value};const i=R.findIndex(x=>x.profile.name===c.name);if(i>=0){rec.hist=(R[i].hist||[]).concat({date:R[i].date,health:R[i].health,top:R[i].top,equity:R[i].equity});R[i]=rec}else R.unshift(rec);store.set("amr_clients",R);
    if(typeof boardAdd==="function"){[30,90].forEach(d=>boardAdd({t:`${d}-day follow-up: ${c.name} — ${rec.top}`,due:new Date(Date.now()+d*86400000).toISOString(),owner:"ISA",src:"annual review"},false))}
    if(typeof emit==="function")emit("annual.review_done",{name:c.name,email:c.email,phone:c.phone,next_review:rec.next,top_opportunity:rec.top,review_date:rec.date});$("#am_msg").textContent=`Saved. Next review ${rec.next}. 30- and 90-day follow-ups added to the Handoff Board.`};draw()}],
 ["sop","Review SOP & checklist",()=>{const W=store.get("amr_chk",{});return `<div class="card"><h4>The annual review system</h4><p class="sm">Goal: every past client gets a 20-minute check-up each year; opportunities become files; every review earns a referral ask.</p>${AMR_SOP.map((s,si)=>`<details class="card" ${si===0?"open":""}><summary><b>${esc(s[0])}</b></summary>${s[1].map((x,i)=>`<label class="chk" style="display:block;margin:5px 0"><input type="checkbox" class="am-ck" data-k="${si}_${i}" ${W[si+"_"+i]?"checked":""}> ${esc(x)}</label>`).join("")}</details>`).join("")}<button class="btn ghost sm" id="am_ckr">Reset checklist</button></div><div class="grid g2"><div class="card"><h4>Triggers that should start a review early</h4>${omList(["Rate falls ≥0.5% below the client's rate (VA IRRRL / refi)","Equity grew enough for a HELOC/cash-out/MI removal","PMI at or near 80% LTV","ARM nearing reset","Client life event: retirement, divorce, inheritance, PCS, new baby","Client turns 62 (reverse mortgage education)","Insurance or tax bill jumps","Partner (CPA/advisor/realtor) asks for a review"])}</div><div class="card"><h4>What the review is NOT</h4>${omList(["A sales pitch — 'nothing to do' is a valid, trust-building result","Tax or legal advice","A rate quote or commitment to lend","An excuse to churn loans — document net tangible benefit"])}</div></div>`},
  ()=>{$$(".am-ck").forEach(c=>c.onchange=()=>{const W=store.get("amr_chk",{});W[c.dataset.k]=c.checked;store.set("amr_chk",W)});$("#am_ckr").onclick=()=>{store.set("amr_chk",{});$("#am_body").innerHTML=tabs[1][2]();tabs[1][3]()}}],
 ["tpl","Scripts & templates",()=>`<div class="grid g2">${AMR_TEMPLATES.map((t,i)=>`<div class="card"><h4>${esc(t[0])}</h4><pre class="sm" style="white-space:pre-wrap">${esc(t[1])}</pre><button class="btn ghost sm am-cp" data-i="${i}">Copy</button></div>`).join("")}</div>`,
  ()=>{$$(".am-cp").forEach(b=>b.onclick=()=>{copy(AMR_TEMPLATES[+b.dataset.i][1].replace("{disclosure}",cfg().disclosure||""));toast("Copied")})}],
 ["log","Review log & due list",()=>`<div class="card"><div class="row"><b>Past reviews</b><span class="sp"></span><button class="btn ghost sm" id="al_csv">Export CSV</button><button class="btn sm" id="al_due">Queue invites for due reviews</button></div><div id="al_l"></div></div>`,
  ()=>{const R=()=>store.get("amr_clients",[]);const draw=()=>{const A=R();$("#al_l").innerHTML=A.length?`<table><thead><tr><th>Client</th><th>Last review</th><th>Next due</th><th>Health</th><th>Top opportunity</th><th>Equity</th><th></th></tr></thead><tbody>${A.map((r,i)=>{const d=cnDays(r.next);return `<tr><td><b>${esc(r.profile.name)}</b><div class="sm mut">${esc(r.profile.phone||"")} ${esc(r.profile.email||"")}</div></td><td>${esc(r.date)}</td><td>${esc(r.next)} <span class="tag ${d!=null&&d<=30?"warn":""}">${d}d</span></td><td>${r.health}${(r.hist||[]).length?` <span class="sm mut">(was ${r.hist[r.hist.length-1].health})</span>`:""}</td><td class="sm">${esc(r.top)}</td><td>${money(r.equity)}</td><td><button class="btn ghost sm al-o" data-i="${i}">Open</button> <button class="btn ghost sm al-x" data-i="${i}">✕</button></td></tr>`}).join("")}</tbody></table>`:'<p class="mut">No reviews saved yet. Complete one in the Client review tab.</p>'};
   $("#al_l").addEventListener("click",e=>{const o=e.target.closest(".al-o"),x=e.target.closest(".al-x");const A=R();if(o){store.set("amr_cur",A[+o.dataset.i].profile);$$("#am_tabs [data-t=\"rev\"]")[0].click()}if(x){A.splice(+x.dataset.i,1);store.set("amr_clients",A);draw()}});
   $("#al_csv").onclick=()=>cnDownload("annual-reviews.csv",cnToCSV(["name","phone","email","date","next","health","top","equity"],R().map(r=>({name:r.profile.name,phone:r.profile.phone,email:r.profile.email,date:r.date,next:r.next,health:r.health,top:r.top,equity:Math.round(r.equity)}))));
   $("#al_due").onclick=()=>{const A=R().filter(r=>{const d=cnDays(r.next);return d!=null&&d<=30});A.forEach(r=>{if(typeof emit==="function")emit("annual.review_due",{name:r.profile.name,phone:r.profile.phone,email:r.profile.email,last_review:r.date,due_date:r.next});if(typeof boardAdd==="function")boardAdd({t:`Invite for annual review: ${r.profile.name}`,due:new Date().toISOString(),owner:"ISA",src:"annual review"},false)});toast(A.length+" review invitations queued")};draw()}]
 ];omTabs("amtab","am","rev",tabs).run()}};

/* ---------------- wiring ---------------- */
{const l=PAGES.find(p=>p[0]==="Loan Intelligence");const o=PAGES.find(p=>p[0]==="Operate");const g=PAGES.find(p=>p[0]==="Growth & Ops");if(l&&!l[1].some(x=>x[0]==="equity"))l[1].splice(2,0,["equity","Equity, Refi & Reverse"]);if(o&&!o[1].some(x=>x[0]==="annual"))o[1].splice(5,0,["annual","Annual Mortgage Review"]);if(g&&!g[1].some(x=>x[0]==="refer"))g[1].splice(2,0,["refer","Referral Partner Playbooks"])}
{const c0=coachCorpus;coachCorpus=function(){const out=c0();EQ_PRODUCTS.forEach(p=>out.push({src:`Product — ${p.n}`,t:`${p.what} Best for: ${p.who.join("; ")}. Process: ${p.flow.join("; ")} Pros: ${p.pros.join("; ")} Cons: ${p.cons.join("; ")}`}));EQ_FAQ.forEach(f=>out.push({src:`Equity FAQ — ${f[0]}`,t:f[1]}));RP_TYPES.forEach(t=>out.push({src:`Referral partner — ${t.n}`,t:`${t.why} Lead with: ${t.lead.join("; ")} First touch: ${t.first} Compliance: ${t.comp.join("; ")}`}));AMR_SOP.forEach(s=>out.push({src:`Annual review SOP — ${s[0]}`,t:s[1].join("; ")}));return out}}
if(typeof SEARCH_ROUTES!=="undefined")SEARCH_ROUTES.unshift([/^Product — |^Equity FAQ — /,{hash:"equity"}],[/^Referral partner — /,{hash:"refer"}],[/^Annual review SOP — /,{hash:"annual"}]);
boot();
